export const code = async (inputs) => {
  const payload = typeof inputs.payload === 'string' ? JSON.parse(inputs.payload) : (inputs.payload || {});
  const attendance = payload.attendance || [];
  const students = payload.students || [];
  const batches = payload.batches || [];
  const date = payload.date || new Date().toISOString().split('T')[0];
  const alreadyNotified = payload.alreadyNotified || [];

  const studentMap = {};
  students.forEach(s => { studentMap[s.id] = s; });
  const batchMap = {};
  batches.forEach(b => { batchMap[b.id] = b; });

  const emails = [];
  const skipped = [];

  attendance.forEach(a => {
    if (a.status !== 'ABSENT') return;
    const student = studentMap[a.studentId];
    if (!student || !student.guardianEmail) {
      skipped.push({ studentId: a.studentId, reason: 'missing_email' });
      return;
    }
    const notificationKey = a.studentId + '|' + a.batchId + '|' + date;
    if (alreadyNotified.includes(notificationKey)) {
      skipped.push({ studentId: a.studentId, reason: 'already_notified' });
      return;
    }
    const batch = batchMap[a.batchId] || {};
    emails.push({
      studentId: a.studentId,
      studentName: student.name || 'Student',
      guardianEmail: student.guardianEmail,
      batchName: (batch.program || '') + ' ' + (batch.dayPattern || ''),
      batchDate: date,
      batchTime: (batch.startTime || '') + ' - ' + (batch.endTime || ''),
      subject: `Attendance Notification — ${student.name}`,
      body: `Dear Parent/Guardian,

This is to inform you that ${student.name} was marked absent for their scheduled tennis session.

Batch: ${batch.program || ''} ${batch.dayPattern || ''}
Date: ${date}
Time: ${batch.startTime || ''} — ${batch.endTime || ''}

Regards,
Tennis Academy Management`
    });
  });

  return { emails, skipped, totalAbsent: attendance.filter(a => a.status === 'ABSENT').length, emailsToSend: emails.length, skippedCount: skipped.length };
};
